    a=[r[:] for r in g]; H=len(g); W=len(g[0])
    # find main object containing 5 and 8, and lower colored tile
    objs=[]
    seen=set()
    for r in range(H):
      for c in range(W):
       if g[r][c] and (r,c) not in seen:
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
         x,y=stack.pop(); cells.append((x,y))
         for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
          q=(x+dx,y+dy)
          if 0<=q[0]<H and 0<=q[1]<W and g[q[0]][q[1]] and q not in seen: seen.add(q); stack.append(q)
        objs.append(cells)
    main=max([o for o in objs if any(g[x][y]==8 for x,y in o)],key=len)
    other=[o for o in objs if o!=main and any(g[x][y]==5 for x,y in o)]
    tile=max(other,key=len)
    # tile's 5 component bbox and other color
    five=[(x,y) for x,y in tile if g[x][y]==5]; color=next(g[x][y] for x,y in tile if g[x][y]!=5)
    r0=min(x for x,y in five); c0=min(y for x,y in five)
    h=max(x for x,y in five)-r0+1; w=max(y for x,y in five)-c0+1
    mr=min(x for x,y in main); mc=min(y for x,y in main)
    for x,y in main:
      val=g[x][y]
      for i in range(h):
       for j in range(w):
        rr=r0+(x-mr)*h+i; cc=c0+(y-mc)*w+j
        if 0<=rr<H and 0<=cc<W: a[rr][cc]= color if val==8 else 5
    return a"}

